"""Rotate old entries from app.log into archive.log.

Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp (integer seconds). Every line in app.log starts
with a YYYY-MM-DD HH:MM:SS timestamp. Entries strictly older than 7 days
before AS_OF are moved to archive.log; remaining entries stay in app.log.
Order is preserved in both files.
"""

import sys
from datetime import datetime, timezone


def parse_timestamp(line: str) -> datetime | None:
    """Try to parse a YYYY-MM-DD HH:MM:SS prefix from the line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    as_of_dt = datetime.fromtimestamp(as_of, tz=timezone.utc)
    cutoff = as_of_dt.timestamp() - 7 * 86400  # 7 days in seconds

    # Read all entries from app.log
    try:
        with open("app.log") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("app.log not found", file=sys.stderr)
        sys.exit(1)

    keep: list[str] = []
    archive: list[str] = []

    for line in lines:
        dt = parse_timestamp(line)
        if dt is not None and dt.timestamp() < cutoff:
            archive.append(line)
        else:
            keep.append(line)

    # Append old entries to archive.log
    if archive:
        with open("archive.log", "a") as f:
            f.writelines(archive)

    # Rewrite app.log with remaining entries
    with open("app.log", "w") as f:
        f.writelines(keep)


if __name__ == "__main__":
    main()

